def format_table(zeilen):
    if not zeilen:
        return ""

    # Finde die maximale Breite für jede Spalte
    spalten_anzahl = max(len(zeile) for zeile in zeilen)
    spalten_breiten = [0] * spalten_anzahl

    for zeile in zeilen:
        for i, zelle in enumerate(zeile):
            if len(zelle) > spalten_breiten[i]:
                spalten_breiten[i] = len(zelle)

    # Erzeuge die formatierte Tabelle
    ergebnis = []
    for zeile in zeilen:
        formatierte_zeile = "|"
        for i, zelle in enumerate(zeile):
            formatierte_zeile += f" {zelle:{spalten_breiten[i]}} |"
        ergebnis.append(formatierte_zeile)

    return "\n".join(ergebnis)
